"use strict";
(()=>{
 const params=new URLSearchParams(location.search);const direction=params.get('direction')==='field'?'field':'studio';document.documentElement.dataset.direction=direction;
 document.querySelectorAll('[data-direction-link]').forEach(link=>{if(link.dataset.directionLink===direction)link.setAttribute('aria-current','page');else link.removeAttribute('aria-current');});
 const status=document.querySelector('#page-status');
 function showRole(role){document.querySelectorAll('[data-role-panel]').forEach(p=>p.hidden=p.dataset.rolePanel!==role);document.querySelectorAll('[data-role]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.role===role)));document.querySelector('.app-word span').textContent=role==='pt'?'/ Không gian PT':'/ Không gian học viên';status.textContent=role==='pt'?'Đang xem không gian PT, dữ liệu giả.':'Đang xem thông tin được chia sẻ với học viên, dữ liệu giả.';}
 document.querySelectorAll('[data-role]').forEach(b=>{b.disabled=false;b.addEventListener('click',()=>showRole(b.dataset.role));});
 const learnerButton=document.querySelector('[data-show-learner]');learnerButton.disabled=false;learnerButton.addEventListener('click',()=>{showRole('trainee');document.querySelector('#product').scrollIntoView({behavior:matchMedia('(prefers-reduced-motion:reduce)').matches?'instant':'smooth'});document.querySelector('[data-role="trainee"]').focus({preventScroll:true});});
 const dialog=document.querySelector('#review-dialog');const open=document.querySelector('[data-open-review]');open.disabled=false;open.addEventListener('click',()=>dialog.showModal());document.querySelector('.close-dialog').addEventListener('click',()=>dialog.close());
 dialog.addEventListener('keydown',event=>{if(event.key!=='Tab')return;const focusable=[...dialog.querySelectorAll('button:not(:disabled),input:not(:disabled),a[href]')];const first=focusable[0],last=focusable[focusable.length-1];if(event.shiftKey&&document.activeElement===first){event.preventDefault();last.focus();}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first.focus();}});
 const check=document.querySelector('#review-checkbox'),confirm=document.querySelector('#confirm-review');check.addEventListener('change',()=>confirm.disabled=!check.checked);confirm.addEventListener('click',()=>{if(!check.checked)return;document.querySelector('#review-result').textContent='Đã mô phỏng xác nhận. Không lưu dữ liệu thật.';confirm.disabled=true;check.disabled=true;});
 if(!matchMedia('(prefers-reduced-motion:reduce)').matches){const observer=new IntersectionObserver(entries=>entries.forEach(entry=>{if(entry.isIntersecting){entry.target.classList.add('arriving');observer.unobserve(entry.target);}}),{threshold:.12});document.querySelectorAll('.manifesto>*,.report-copy>*,.report-picture,.connection-heading>*,.connection-grid>*,.questions>h2,.closing .frame>*').forEach(el=>observer.observe(el));}
})();
